class Solution:
    def beautifulNumbers(self, l: int, r: int) -> int:
        def f(N):
            if N <= 0:
                return 0
            s = str(N)
            L = len(s)
            total = 0
            for S in range(1, 9 * L + 1):
                def step(st, sm, pm, d):
                    nsm = sm + d
                    if nsm > S:
                        return None
                    if st or d:
                        return (True, nsm, (pm * d) % S)
                    return (False, nsm, pm)

                free = {}
                tight_alive = True
                tsm = 0
                tpm = 1 % S
                tst = False
                for ch in s:
                    nd = int(ch)
                    nf = {}
                    for (st, sm, pm), c in free.items():
                        for d in range(10):
                            ns = step(st, sm, pm, d)
                            if ns is None:
                                continue
                            nf[ns] = nf.get(ns, 0) + c
                    if tight_alive:
                        for d in range(nd):
                            ns = step(tst, tsm, tpm, d)
                            if ns is None:
                                continue
                            nf[ns] = nf.get(ns, 0) + 1
                        ns = step(tst, tsm, tpm, nd)
                        if ns is None:
                            tight_alive = False
                        else:
                            tst, tsm, tpm = ns
                    free = nf
                cnt = free.get((True, S, 0), 0)
                if tight_alive and tst and tsm == S and tpm == 0:
                    cnt += 1
                total += cnt
            return total

        return f(r) - f(l - 1)
