class Solution:
    def beautifulNumbers(self, l: int, r: int) -> int:
        @lru_cache(maxsize=None)
        def free(k, s, p):
            # Number of ways to append k digits so that final sum s and product p
            # satisfy p % s == 0 (s > 0).
            if k == 0:
                return 1 if s > 0 and p % s == 0 else 0
            total = 0
            for d in range(10):
                total += free(k - 1, s + d, p * d)
            return total

        def count(N):
            if N <= 0:
                return 0
            digits = str(N)
            L = len(digits)
            res = 0
            # Numbers with fewer digits than N
            for m in range(1, L):
                for d in range(1, 10):
                    res += free(m - 1, d, d)
            # Numbers with the same number of digits as N, not exceeding N
            s = 0
            p = 1
            for i, ch in enumerate(digits):
                cd = int(ch)
                start = 1 if i == 0 else 0
                for d in range(start, cd):
                    res += free(L - i - 1, s + d, p * d)
                s += cd
                p *= cd
            if s > 0 and p % s == 0:
                res += 1
            return res

        return count(r) - count(l - 1)
