class Solution:
    def beautifulNumbers(self, l: int, r: int) -> int:
        @lru_cache(maxsize=None)
        def free(rem, sm, pr):
            # number of ways to append rem digits so that final pr % final sm == 0
            if rem == 0:
                return 1 if pr % sm == 0 else 0
            total = 0
            for d in range(10):
                total += free(rem - 1, sm + d, pr * d)
            return total

        def count(n):
            if n <= 0:
                return 0
            s = list(map(int, str(n)))
            L = len(s)
            total = 0
            # numbers with fewer digits than n
            for k in range(1, L):
                for d in range(1, 10):
                    total += free(k - 1, d, d)
            # numbers with the same number of digits as n
            ps = 0
            pp = 1
            for i in range(L):
                start = 1 if i == 0 else 0
                for d in range(start, s[i]):
                    total += free(L - i - 1, ps + d, pp * d)
                ps += s[i]
                pp *= s[i]
            # n itself
            if ps > 0 and pp % ps == 0:
                total += 1
            return total

        return count(r) - count(l - 1)
