    def beautifulNumbers(self, l: int, r: int) -> int:
        # D[k]: dict (sum, product) -> count of digit strings of length k (digits 0-9)
        MAXL = 9
        D = [dict() for _ in range(MAXL + 1)]
        D[0] = {(0, 1): 1}
        for k in range(1, MAXL + 1):
            nxt = {}
            for (s, p), c in D[k - 1].items():
                for d in range(10):
                    key = (s + d, p * d)
                    nxt[key] = nxt.get(key, 0) + c
            D[k] = nxt

        def beautiful(s, p):
            return s > 0 and p % s == 0

        def count(N):
            if N <= 0:
                return 0
            digits = [int(ch) for ch in str(N)]
            L = len(digits)
            total = 0
            # Numbers with fewer digits than N
            for m in range(1, L):
                for d in range(1, 10):
                    for (s, p), c in D[m - 1].items():
                        if beautiful(d + s, d * p):
                            total += c
            # Numbers with exactly L digits, <= N
            ps, pp = 0, 1
            for i in range(L):
                nd = digits[i]
                k = L - i - 1
                start = 1 if i == 0 else 0
                for d in range(start, nd):
                    cs = ps + d
                    cp = pp * d
                    for (s, p), c in D[k].items():
                        if beautiful(cs + s, cp * p):
                            total += c
                ps += nd
                pp *= nd
            if beautiful(ps, pp):
                total += 1
            return total

        return count(r) - count(l - 1)
