class Solution:
    def beautifulNumbers(self, l: int, r: int) -> int:
        def count(N: int) -> int:
            if N <= 0:
                return 0
            digits = list(map(int, str(N)))
            free = defaultdict(int)  # (sum, prod) -> count, strictly below N's prefix
            ts, tp = 0, 1           # tight state: prefix of N

            def step(s, p, d):
                if s == 0 and d == 0:
                    return (0, 1)
                return (s + d, p * d)

            for D in digits:
                newfree = defaultdict(int)
                for (s, p), c in free.items():
                    for d in range(10):
                        newfree[step(s, p, d)] += c
                for d in range(D):
                    newfree[step(ts, tp, d)] += 1
                free = newfree
                ts, tp = step(ts, tp, D)

            total = 0
            for (s, p), c in free.items():
                if s > 0 and p % s == 0:
                    total += c
            if ts > 0 and tp % ts == 0:
                total += 1
            return total

        return count(r) - count(l - 1)
