class Solution:
    def beautifulNumbers(self, l: int, r: int) -> int:
        def count(N: int) -> int:
            if N <= 0:
                return 0
            digits = str(N)
            n = len(digits)

            @lru_cache(maxsize=None)
            def dfs(pos, s, p, tight, started):
                if pos == n:
                    return 1 if started and s > 0 and p % s == 0 else 0
                limit = int(digits[pos]) if tight else 9
                total = 0
                for d in range(0, limit + 1):
                    nt = tight and d == limit
                    if not started and d == 0:
                        total += dfs(pos + 1, 0, 1, nt, False)
                    else:
                        total += dfs(pos + 1, s + d, p * d, nt, True)
                return total

            result = dfs(0, 0, 1, True, False)
            dfs.cache_clear()
            return result

        return count(r) - count(l - 1)
class Solution:
    def beautifulNumbers(self, l: int, r: int) -> int:
        def f(N: int) -> int:
            if N <= 0:
                return 0
            d = [int(c) for c in str(N)]
            n = len(d)
            total = 0
            for S in range(1, 9 * n + 1):
                cur = {}           # free, started states: (sum, prod mod S) -> count
                nf = 0             # free, not-started states (all zeros so far), count
                ts, tm, tst, alive = 0, 1 % S, False, True  # tight state
                for D in d:
                    new = {}

                    def add(s, m, c):
                        key = (s, m)
                        new[key] = new.get(key, 0) + c

                    newnf = nf  # x = 0 keeps not-started
                    # extend free started states
                    for (s, m), c in cur.items():
                        for x in range(10):
                            ns = s + x
                            if ns > S:
                                break
                            add(ns, (m * x) % S, c)
                    # start from free not-started states with nonzero digit
                    if nf:
                        for x in range(1, 10):
                            if x <= S:
                                add(x, x % S, nf)
                    # tight prefix branches with digit x < D
                    if alive:
                        for x in range(D):
                            if tst:
                                ns = ts + x
                                if ns <= S:
                                    add(ns, (tm * x) % S, 1)
                            else:
                                if x == 0:
                                    newnf += 1
                                elif x <= S:
                                    add(x, x % S, 1)
                    # advance tight path by digit D
                    if alive:
                        if tst:
                            ns = ts + D
                            if ns > S:
                                alive = False
                            else:
                                ts = ns
                                tm = (tm * D) % S
                        else:
                            if D > 0:
                                if D > S:
                                    alive = False
                                else:
                                    ts = D
                                    tm = D % S
                                    tst = True
                    nf = newnf
                    cur = new

                total += cur.get((S, 0), 0)
                if alive and tst and ts == S and tm == 0:
                    total += 1
            return total

        return f(r) - f(l - 1)

